using Microsoft.Data.Sqlite;using Accyourate.App.Platform.Notifications;
namespace Accyourate.App.AssetManagement.Services;
public sealed class SupplierRmaCapaGovernanceAction{public int Id{get;init;}public string SourceType{get;init;}="";public string SourceReference{get;init;}="";public string Title{get;init;}="";public string Description{get;init;}="";public string Owner{get;init;}="";public string Priority{get;init;}="Media";public string Status{get;init;}="Aperta";public string DueDate{get;init;}="";public string Evidence{get;init;}="";public string CreatedAt{get;init;}="";public string CreatedBy{get;init;}="";public string ClosedAt{get;init;}="";public string ClosedBy{get;init;}="";public bool IsOverdue=>Status!="Completata"&&DateTime.TryParse(DueDate,out var d)&&d.Date<DateTime.Today;public bool IsDueSoon=>Status!="Completata"&&DateTime.TryParse(DueDate,out var d)&&d.Date>=DateTime.Today&&d.Date<=DateTime.Today.AddDays(7);}
public sealed class SupplierRmaCapaGovernanceActionEvent{public int Id{get;init;}public string EventType{get;init;}="";public string Detail{get;init;}="";public string CreatedAt{get;init;}="";public string CreatedBy{get;init;}="";}
public sealed class SupplierRmaCapaGovernanceActionService
{
 private readonly string _cs;public SupplierRmaCapaGovernanceActionService(string? db=null){var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"AccyourateEnterpriseX");Directory.CreateDirectory(folder);_cs=$"Data Source={db??Path.Combine(folder,"accyourate-assets.db")}";using var c=Open();using var q=c.CreateCommand();q.CommandText="CREATE TABLE IF NOT EXISTS SupplierRmaCapaGovernanceActions(Id INTEGER PRIMARY KEY AUTOINCREMENT,SourceType TEXT NOT NULL,SourceReference TEXT NOT NULL,Title TEXT NOT NULL,Description TEXT NOT NULL,Owner TEXT NOT NULL,Priority TEXT NOT NULL,Status TEXT NOT NULL,DueDate TEXT NOT NULL,Evidence TEXT NOT NULL,CreatedAt TEXT NOT NULL,CreatedBy TEXT NOT NULL,ClosedAt TEXT NOT NULL,ClosedBy TEXT NOT NULL);CREATE TABLE IF NOT EXISTS SupplierRmaCapaGovernanceActionEvents(Id INTEGER PRIMARY KEY AUTOINCREMENT,ActionId INTEGER NOT NULL,EventType TEXT NOT NULL,Detail TEXT NOT NULL,CreatedAt TEXT NOT NULL,CreatedBy TEXT NOT NULL);CREATE TABLE IF NOT EXISTS SupplierRmaCapaGovernanceActionNotifications(NotificationKey TEXT PRIMARY KEY,ActionId INTEGER NOT NULL,CreatedAt TEXT NOT NULL);";q.ExecuteNonQuery();}
 public IReadOnlyList<SupplierRmaCapaGovernanceAction> GetAll(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Id,SourceType,SourceReference,Title,Description,Owner,Priority,Status,DueDate,Evidence,CreatedAt,CreatedBy,ClosedAt,ClosedBy FROM SupplierRmaCapaGovernanceActions ORDER BY CASE Status WHEN 'Aperta' THEN 0 WHEN 'In corso' THEN 1 ELSE 2 END,DueDate,Id DESC;";using var r=q.ExecuteReader();var v=new List<SupplierRmaCapaGovernanceAction>();while(r.Read())v.Add(new(){Id=r.GetInt32(0),SourceType=r.GetString(1),SourceReference=r.GetString(2),Title=r.GetString(3),Description=r.GetString(4),Owner=r.GetString(5),Priority=r.GetString(6),Status=r.GetString(7),DueDate=r.GetString(8),Evidence=r.GetString(9),CreatedAt=r.GetString(10),CreatedBy=r.GetString(11),ClosedAt=r.GetString(12),ClosedBy=r.GetString(13)});return v;}
 public void Create(string source,string reference,string title,string description,string owner,string priority,string due,string user){if(string.IsNullOrWhiteSpace(title)||string.IsNullOrWhiteSpace(owner)||!DateTime.TryParse(due,out var date))throw new InvalidOperationException("Titolo, responsabile e scadenza sono obbligatori.");if(priority is not("Bassa" or "Media" or "Alta" or "Critica"))throw new InvalidOperationException("Priorita non valida.");using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO SupplierRmaCapaGovernanceActions(SourceType,SourceReference,Title,Description,Owner,Priority,Status,DueDate,Evidence,CreatedAt,CreatedBy,ClosedAt,ClosedBy) VALUES($s,$r,$t,$d,$o,$p,'Aperta',$due,'',$at,$u,'','');SELECT last_insert_rowid();";q.Parameters.AddWithValue("$s",source.Trim());q.Parameters.AddWithValue("$r",reference.Trim());q.Parameters.AddWithValue("$t",title.Trim());q.Parameters.AddWithValue("$d",description.Trim());q.Parameters.AddWithValue("$o",owner.Trim());q.Parameters.AddWithValue("$p",priority);q.Parameters.AddWithValue("$due",date.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$at",DateTime.Now.ToString("s"));q.Parameters.AddWithValue("$u",user);var id=Convert.ToInt32(q.ExecuteScalar());Event(c,id,"Creazione",$"Responsabile: {owner}; scadenza: {date:dd/MM/yyyy}; priorita: {priority}",user);}
 public void Start(int id,string user){using var c=Open();using var q=c.CreateCommand();q.CommandText="UPDATE SupplierRmaCapaGovernanceActions SET Status='In corso' WHERE Id=$id AND Status='Aperta';";q.Parameters.AddWithValue("$id",id);if(q.ExecuteNonQuery()==0)throw new InvalidOperationException("L'azione non e nello stato Aperta.");Event(c,id,"Avvio","Azione presa in carico",user);}
 public void Complete(int id,string evidence,string user){if(string.IsNullOrWhiteSpace(evidence))throw new InvalidOperationException("Le evidenze di chiusura sono obbligatorie.");using var c=Open();using var q=c.CreateCommand();q.CommandText="UPDATE SupplierRmaCapaGovernanceActions SET Status='Completata',Evidence=$e,ClosedAt=$d,ClosedBy=$u WHERE Id=$id AND Status<>'Completata';";q.Parameters.AddWithValue("$id",id);q.Parameters.AddWithValue("$e",evidence.Trim());q.Parameters.AddWithValue("$d",DateTime.Now.ToString("s"));q.Parameters.AddWithValue("$u",user);if(q.ExecuteNonQuery()==0)throw new InvalidOperationException("Azione gia completata o non trovata.");Event(c,id,"Chiusura",evidence,user);}
 public void ReopenAfterFailedVerification(int id,string notes,string user){if(string.IsNullOrWhiteSpace(notes))throw new InvalidOperationException("Indica l'esito della verifica.");using var c=Open();using var q=c.CreateCommand();q.CommandText="UPDATE SupplierRmaCapaGovernanceActions SET Status='In corso',ClosedAt='',ClosedBy='' WHERE Id=$id AND Status='Completata';";q.Parameters.AddWithValue("$id",id);if(q.ExecuteNonQuery()==0)throw new InvalidOperationException("L'azione non risulta completata.");Event(c,id,"Verifica non superata",notes.Trim(),user);}
 public IReadOnlyList<SupplierRmaCapaGovernanceActionEvent> History(int id){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Id,EventType,Detail,CreatedAt,CreatedBy FROM SupplierRmaCapaGovernanceActionEvents WHERE ActionId=$id ORDER BY Id DESC;";q.Parameters.AddWithValue("$id",id);using var r=q.ExecuteReader();var v=new List<SupplierRmaCapaGovernanceActionEvent>();while(r.Read())v.Add(new(){Id=r.GetInt32(0),EventType=r.GetString(1),Detail=r.GetString(2),CreatedAt=r.GetString(3),CreatedBy=r.GetString(4)});return v;}
 public int PublishAlerts(NotificationService? n=null){n??=new NotificationService();var count=0;foreach(var x in GetAll().Where(x=>x.IsOverdue||x.IsDueSoon)){var key=$"capa-governance-action:{x.Id}:{(x.IsOverdue?"overdue":"due")}:{DateTime.Today:yyyyMMdd}";using var c=Open();using var check=c.CreateCommand();check.CommandText="SELECT COUNT(*) FROM SupplierRmaCapaGovernanceActionNotifications WHERE NotificationKey=$k;";check.Parameters.AddWithValue("$k",key);if(Convert.ToInt32(check.ExecuteScalar())>0)continue;n.Publish(x.IsOverdue?"Azione Governance CAPA scaduta":"Azione Governance CAPA in scadenza",$"{x.Title} - responsabile {x.Owner}, scadenza {Date(x.DueDate)}.",NotificationCategory.Asset,x.IsOverdue?NotificationPriority.Critical:NotificationPriority.High,"Piano azioni Governance CAPA","open-rma-corrective-actions",x.Id.ToString());using var add=c.CreateCommand();add.CommandText="INSERT INTO SupplierRmaCapaGovernanceActionNotifications(NotificationKey,ActionId,CreatedAt) VALUES($k,$id,$d);";add.Parameters.AddWithValue("$k",key);add.Parameters.AddWithValue("$id",x.Id);add.Parameters.AddWithValue("$d",DateTime.Now.ToString("s"));add.ExecuteNonQuery();count++;}return count;}
 private static string Date(string v)=>DateTime.TryParse(v,out var d)?d.ToString("dd/MM/yyyy"):v;private static void Event(SqliteConnection c,int id,string type,string detail,string user){using var q=c.CreateCommand();q.CommandText="INSERT INTO SupplierRmaCapaGovernanceActionEvents(ActionId,EventType,Detail,CreatedAt,CreatedBy) VALUES($id,$t,$d,$at,$u);";q.Parameters.AddWithValue("$id",id);q.Parameters.AddWithValue("$t",type);q.Parameters.AddWithValue("$d",detail);q.Parameters.AddWithValue("$at",DateTime.Now.ToString("s"));q.Parameters.AddWithValue("$u",user);q.ExecuteNonQuery();}private SqliteConnection Open(){var c=new SqliteConnection(_cs);c.Open();return c;}
}
